// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address sender) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 0, address(c).balance);
        vm.deal(sender, amount);

        uint256 balanceBefore = c.getBalance(sender);
        vm.prank(sender);
        c.addToBalance{value: amount}();
        uint256 balanceAfter = c.getBalance(sender);

        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
